(* [comment removed for export] *)
Definition immf_post (ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (a0 a2 : word) (src : list byte) (m : word -> option byte) : machine_state -> Prop :=
  fun ms' => exists a1' a2' a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned a0, bv_unsigned a0 + bv_unsigned a2)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ rw_cells bsegs m' (bv_unsigned a0) [CB (Z.to_nat (bv_unsigned a2)) src].

Lemma skipn_cons_nth : forall {A} (l : list A) i x, nth_error l i = Some x -> skipn i l = x :: skipn (S i) l.
Proof.
  intros A l. induction l as [|y l IH]; intros [|i] x Hn; cbn in Hn |- *; try discriminate.
  - inversion Hn; subst. reflexivity.
  - apply IH. exact Hn.
Qed.

Section IMMF.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (src junk : list byte).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis SRC : bytes_at bsegs m (bv_unsigned a1) src.
  Hypothesis LEN : length src = Z.to_nat (bv_unsigned a2).
  Hypothesis DST : rw_cells bsegs m (bv_unsigned a0) [CB (Z.to_nat (bv_unsigned a2)) junk].
  Hypothesis FWD : bv_unsigned a0 < bv_unsigned a1.
  Hypothesis N63 : bv_unsigned a2 < 2^63.
  Hypothesis TOP : bv_unsigned a0 + bv_unsigned a2 < 2^64 /\ bv_unsigned a1 + bv_unsigned a2 < 2^64.

  Notation dst := (bv_unsigned a0).
  Notation sa := (bv_unsigned a1).
  Notation n := (bv_unsigned a2).
  Notation POST := (immf_post ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc a0 a2 src m).
  Notation W := [(bv_unsigned a0, bv_unsigned a0 + bv_unsigned a2)]%Z.
  Notation ST pc x11 x12 x13 x14 x15 x16 mm :=
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 x11 x12 x13 x14 x15 x16 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mm (seg_rom bsegs)).

  Lemma junkf_len : length junk = length src.
  Proof. pose proof (proj1 (proj1 (proj1 DST))) as H. cbn in H. rewrite LEN. exact H. Qed.

