    (* [comment removed for export] *)
    Lemma immf_fwd : forall (k : nat) (i : Z) w11 w13 x14 x15 x16 mcur,
      Z.to_nat (n - i) = k -> 0 <= i < n -> w11 = Z_to_bv 64 (sa + i) -> w13 = Z_to_bv 64 (dst + i) ->
      mem_inv bsegs mcur -> bytes_at bsegs mcur (sa + i) (skipn (Z.to_nat i) src) -> munch W m mcur -> wmono bsegs m mcur ->
      u8arr bsegs mcur dst (firstn (Z.to_nat i) src ++ skipn (Z.to_nat i) junk) ->
      evt bsegs POST (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 w11 (Z_to_bv 64 (dst + n)) w13 x14 x15 x16 a7
                           s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
